/* Banco de preguntas - NIVEL DIFÍCIL (temas 1 a 10)
   Preguntas de literalidad, con opciones casi idénticas y juegos de léxico.
   Mismo formato que B(...), pero con D(...) quedan marcadas como difíciles. */
function D() { window.B.apply(null, arguments); window.BANCO[window.BANCO.length - 1].d = 1; }

/* ================= TEMA 1 ================= */
D(1,"T","Según el artículo 14.2 del Estatuto de Personal No Sanitario, los celadores tramitarán o conducirán las comunicaciones, documentos, correspondencia u objetos que les confíen sus superiores:","Sin tardanza",["Sin demora injustificada","Con la mayor diligencia","A la mayor brevedad posible"],"Literal de la función 1ª: 'tramitarán o conducirán sin tardanza'. Las otras expresiones significan lo mismo pero no son las del Estatuto.");
D(1,"T","La función 1ª del artículo 14.2 se refiere a las comunicaciones:","Verbales",["Escritas","Oficiales","Telefónicas"],"'Comunicaciones verbales, documentos, correspondencia u objetos'. Lo escrito queda cubierto por 'documentos' y 'correspondencia'.");
D(1,"T","Además de tramitar comunicaciones y documentos, la función 1ª del artículo 14.2 obliga a los celadores a trasladar, en su caso, de unos servicios a otros:","Los aparatos o mobiliario que se requiera",["Los aparatos o instrumental que se requiera","El mobiliario o lencería que se requiera","Los aparatos o medicamentos que se requiera"],"Literal: 'los aparatos o mobiliario que se requiera'.");
D(1,"T","El celador realizará excepcionalmente labores de limpieza cuando su realización por el personal femenino:","No sea idónea o decorosa",["No sea idónea o posible","No sea decorosa o segura","No sea posible o conveniente"],"Función 3ª: 'no sea idónea o decorosa'.");
D(1,"T","Señale el criterio que NO menciona la función 3ª del artículo 14.2 para encomendar labores de limpieza al celador:","El horario en que deban realizarse",["La situación o emplazamiento","La dificultad de manejo","El peso de los objetos o locales a limpiar"],"La función cita: situación, emplazamiento, dificultad de manejo y peso de los objetos o locales a limpiar.");
D(1,"T","Según la función 4ª, los celadores instruirán a los enfermos en el uso y manejo de:","Las persianas, cortinas y útiles de servicio en general",["Las persianas, camas y útiles de servicio en general","Las cortinas, timbres y útiles de aseo en general","Las persianas, cortinas y enseres de la habitación"],"Literal de la función 4ª. 'Enseres y ropas' aparece antes, referido al uso indebido.");
D(1,"T","Cuidar de que los enfermos no hagan uso indebido de los enseres y ropas de la Institución corresponde, según el Estatuto:","A los celadores, al igual que al resto del personal",["A los celadores en exclusiva","Al Jefe de Personal Subalterno","A las supervisoras de planta en exclusiva"],"Función 4ª: 'Cuidarán, al igual que el resto del personal...'.");
D(1,"T","Los celadores servirán de ascensoristas:","Cuando se les asigne especialmente ese cometido o las necesidades del servicio lo requieran",["Cuando se les asigne excepcionalmente ese cometido o las necesidades del servicio lo requieran","Cuando se les asigne especialmente ese cometido y las necesidades del servicio lo requieran","Únicamente cuando lo ordene el Jefe de Personal Subalterno"],"Función 5ª. Trampas: 'especialmente' (no 'excepcionalmente') y la conjunción 'o' (no 'y').");
D(1,"T","En la vigilancia nocturna, el celador cuidará de que estén cerradas las puertas de:","Servicios complementarios",["Servicios generales","Servicios centrales","Servicios auxiliares"],"Función 7ª: 'del que cuidarán estén cerradas las puertas de servicios complementarios'.");
D(1,"T","Según la función 8ª, los celadores velarán continuamente por conseguir:","El mayor orden y silencio posible en todas las dependencias de la Institución",["El mayor orden y limpieza posible en todas las dependencias de la Institución","El mayor orden y silencio posible en las unidades de hospitalización","El mayor silencio y decoro posible en todas las dependencias de la Institución"],"Literal de la función 8ª: orden y silencio, en todas las dependencias.");
D(1,"T","Dar cuenta 'al Administrador' de los desperfectos o alteraciones que encuentre en el edificio es función de:","El Jefe de Personal Subalterno",["El celador","El celador encargado de turno","La supervisora de la unidad"],"El celador da cuenta 'a sus inmediatos superiores' (14.2, 9ª); el Jefe de Personal Subalterno, 'al Administrador' (14.1).");
D(1,"T","La función 9ª del artículo 14.2 obliga al celador a dar cuenta de los desperfectos o anomalías que encontrare en:","La limpieza y conservación del edificio y material",["La limpieza y seguridad del edificio y material","La conservación y mantenimiento del edificio e instalaciones","El orden y conservación del edificio y mobiliario"],"Literal: 'en la limpieza y conservación del edificio y material'.");
D(1,"T","Según la función 11ª, los celadores cuidarán de que no deambulen por pasillos y dependencias más de lo necesario:","Los visitantes que no tengan asuntos que tratar",["Los enfermos que no tengan pruebas pendientes","Los visitantes fuera del horario de visita","Los enfermos y visitantes en general"],"Literal: 'los visitantes que no tengan asuntos que tratar no deambulen por los pasillos y dependencias más que lo necesario para llegar al lugar donde concretamente se dirijan'.");
D(1,"T","La función 13ª establece que los celadores ayudarán al movimiento y traslado de los enfermos encamados que requieran un trato especial a:","Las Enfermeras y Ayudantes de planta",["Las Enfermeras y Auxiliares de clínica","Las Supervisoras y Enfermeras de planta","Los Médicos y Enfermeras de planta"],"El Estatuto de 1971 habla de 'Enfermeras y Ayudantes de planta'.");
D(1,"T","El término 'excepcionalmente' figura en la función del artículo 14.2 relativa a:","Lavar y asear a los enfermos masculinos encamados",["Bañar a los enfermos masculinos","Rasurar a los enfermos masculinos","Servir de ascensoristas"],"Solo lo contienen la 3ª (limpieza) y la 14ª (lavar y asear). Bañar (17ª) no lo lleva.");
D(1,"T","El celador bañará a los enfermos masculinos cuando no puedan hacerlo por sí mismos:","Siempre de acuerdo con las instrucciones que reciba de las Supervisoras de plantas o servicios o personas que las sustituyan",["Excepcionalmente y de acuerdo con las instrucciones de las Enfermeras de planta","Siempre de acuerdo con las instrucciones que reciba del Médico responsable del enfermo","Solo en ausencia del personal auxiliar y por orden del Jefe de Personal Subalterno"],"Función 17ª. No incluye 'excepcionalmente'.");
D(1,"T","La función de rasurar a los enfermos masculinos que vayan a ser intervenidos se limita a:","Aquellas zonas de su cuerpo que lo requieran",["La zona facial y torácica","Las zonas que indique el propio enfermo","Las zonas que no sean íntimas"],"Función 15ª: 'en aquellas zonas de su cuerpo que lo requieran'.");
D(1,"T","La ayuda del celador en la colocación y retirada de las cuñas procede cuando, por circunstancias especiales concurrentes en el enfermo, este no pueda ser movido solo por:","La Enfermera o Ayudante de planta",["La Enfermera o el Médico","La Supervisora o Enfermera","El Ayudante de planta o el familiar"],"Función 18ª.");
D(1,"T","En la práctica de autopsias, el celador ayudará en las funciones auxiliares que no requieran por su parte:","Hacer uso de instrumental alguno sobre el cadáver",["Hacer uso de instrumental quirúrgico alguno sobre el cadáver","Hacer uso de instrumental cortante sobre el cadáver","Entrar en contacto directo con el cadáver"],"Función 20ª: 'instrumental alguno', sin adjetivos. Cualquier instrumental queda excluido.");
D(1,"T","El cuidado de los animales de quirófanos experimentales y laboratorios por el celador se realiza:","Tanto antes de ser sometidos a las pruebas experimentales como después de aquellas",["Únicamente antes de ser sometidos a las pruebas experimentales","Únicamente después de las pruebas experimentales","Solo durante las pruebas, sujetándolos"],"Función 21ª, siempre bajo las indicaciones de Médicos, Supervisoras o Enfermeras.");
D(1,"T","Según la función 22ª, el celador se abstendrá de hacer comentarios con los familiares y visitantes sobre diagnósticos, exploraciones y tratamientos, 'y mucho menos':","Informar sobre los pronósticos de su enfermedad",["Informar sobre las pruebas pendientes","Opinar sobre el personal que le atiende","Informar sobre la fecha prevista del alta"],"Literal de la función 22ª.");
D(1,"T","La función 23ª (cláusula de cierre) atribuye al celador las funciones similares a las anteriores que:","Le sean encomendadas por sus superiores y no hayan quedado específicamente reseñadas",["Le sean encomendadas por el personal sanitario y no hayan quedado específicamente reseñadas","Le sean encomendadas por sus superiores, aunque no sean similares a las reseñadas","Le sean encomendadas por la Dirección por escrito"],"Deben ser funciones 'similares a las anteriores' y encomendadas 'por sus superiores'.");
D(1,"T","El Jefe de Personal Subalterno ejerce la jefatura del personal de celadores:","Por delegación del Director Gerente o del Administrador",["Por delegación del Director Médico o del Administrador","Por nombramiento del Director Gerente y del Administrador","Por delegación de la Dirección de Enfermería"],"Artículo 14.1, función 1ª.");
D(1,"T","Según el artículo 14.1, el Jefe de Personal Subalterno ejercerá, respecto de los paquetes y bultos de que sean portadoras las personas ajenas a la Institución:","El debido y discreto control",["El debido y estricto control","El registro y la custodia","La apertura y comprobación"],"Literal: 'el debido y discreto control de paquetes y bultos'.");
D(1,"T","Vigilar 'personalmente' la limpieza de la Institución es función de:","El Jefe de Personal Subalterno",["El celador","El Administrador","El personal de la Escala de Servicios"],"Artículo 14.1. El celador solo da cuenta de las anomalías que encuentre en la limpieza.");
D(1,"T","El Jefe de Personal Subalterno constatará que cumple el horario establecido y permanece constantemente en su puesto de trabajo:","El personal de oficio y subalterno",["El personal subalterno exclusivamente","El personal subalterno y sanitario no facultativo","Todo el personal no sanitario"],"Artículo 14.1: 'el personal de oficio y subalterno'.");
D(1,"T","Cuidar de la compostura y aseo del personal, revisando y exigiendo que vista el uniforme reglamentario, corresponde a:","El Jefe de Personal Subalterno, respecto del personal a sus órdenes",["El Administrador, respecto de todo el personal","La Dirección de Gestión, respecto del personal subalterno","Cada celador, respecto de sus compañeros de turno"],"Artículo 14.1.");
D(1,"T","Los servicios de guardia que deben hacer los celadores son, según la función 2ª:","Los que correspondan dentro de los turnos que se establezcan",["Los que correspondan dentro de los turnos que soliciten","Los que voluntariamente acepten","Los que fije el Jefe de Personal Subalterno fuera de los turnos"],"Literal de la función 2ª.");
D(1,"T","El Estatuto de Personal No Sanitario se publicó en el BOE el:","22 de julio de 1971",["5 de julio de 1971","26 de abril de 1973","23 de diciembre de 1966"],"La Orden es de 5 de julio; su publicación en el BOE (núm. 174) es de 22 de julio de 1971.");
D(1,"T","En la Escala de Servicios del personal subalterno del Estatuto de 1971 NO se encuadra:","El celador",["La lavandera","El fogonero","La planchadora"],"El celador pertenece a la Escala General, junto con el Jefe de Personal Subalterno.");
D(1,"T","La distancia que mantienen los interlocutores y el uso que hacen del espacio durante la comunicación es objeto de estudio de:","La proxémica",["La kinésica","La paralingüística","La semántica"],"Kinésica: gestos y posturas. Paralingüística: tono, volumen, ritmo.");
D(1,"T","La escucha en la que el receptor atiende, comprende y demuestra al emisor que le está entendiendo se denomina:","Escucha activa",["Escucha selectiva","Escucha pasiva","Escucha reflexiva diferida"],"Incluye mirar, asentir, parafrasear y no interrumpir.");
D(1,"P","A las tres de la madrugada, un celador encuentra una fuga de agua en un pasillo. Atendiendo a la literalidad del artículo 14.2, debe dar cuenta a:","Sus inmediatos superiores",["El Administrador","La Dirección","El servicio de mantenimiento, directamente"],"La función 9ª dice 'a sus inmediatos superiores'. Quien da cuenta 'al Administrador' es el Jefe de Personal Subalterno.");
D(1,"P","Un visitante autorizado sube a planta con un paquete voluminoso. Según la función 10ª, el celador solo permitirá que lo introduzca si:","Está expresamente autorizado por la Dirección",["Está expresamente autorizado por la supervisora","Lo autoriza el enfermo destinatario","No contiene alimentos ni tabaco"],"'Cuidando no introduzcan en las Instituciones más que aquellos paquetes expresamente autorizados por la Dirección'.");
D(1,"P","La supervisora de una unidad pide a un celador que mueva un armario pesado y limpie detrás de él. Conforme al Estatuto:","Debe hacerlo: es un supuesto en que la limpieza se le puede encomendar excepcionalmente por el peso y la dificultad de manejo",["No debe hacerlo: la limpieza nunca es función del celador","Debe mover el armario, pero la limpieza solo puede ordenársela el Jefe de Personal Subalterno","Solo debe hacerlo si no hay personal de limpieza en todo el centro"],"Funciones 1ª (trasladar mobiliario) y 3ª (limpieza excepcional por peso o dificultad de manejo).");
D(1,"P","Un enfermo masculino encamado necesita ser bañado y otro necesita ser rasurado para una intervención urgente. Respecto a ambas tareas, el celador:","Baña al primero según instrucciones de la supervisora y rasura al segundo por la urgencia del tratamiento",["Baña al primero solo excepcionalmente y rasura al segundo solo si falta el peluquero","No realiza ninguna de las dos, por ser funciones de enfermería","Rasura al segundo, pero el baño corresponde siempre al personal auxiliar"],"Bañar (17ª) no es 'excepcional'; rasurar (15ª) procede por ausencia del peluquero 'o' por urgencia.");
D(1,"P","La familia de un fallecido pregunta al celador de planta por los trámites del enterramiento. Lo correcto, según el Estatuto, es:","Remitirles al Jefe de Personal Subalterno, a quien corresponde informar de esos trámites",["Informarles él mismo, por ser función del celador del mortuorio","Remitirles al médico que certificó la muerte","Remitirles directamente a la funeraria de guardia"],"Artículo 14.1: informará a los familiares de los fallecidos sobre los trámites precisos para los enterramientos.");

/* ================= TEMA 2 ================= */
D(2,"T","El aparato acoplado a la bala de oxígeno que indica la presión del gas en su interior, y por tanto su carga, es el:","Manómetro",["Caudalímetro","Humidificador","Manorreductor"],"El caudalímetro mide el flujo en litros por minuto; el manorreductor reduce la presión de salida.");
D(2,"T","El aparato que regula y mide el flujo de oxígeno que se administra al paciente, en litros por minuto, es el:","Caudalímetro o flujómetro",["Manómetro","Manorreductor","Esfigmomanómetro"],"El manómetro mide presión, no flujo.");
D(2,"T","La cama con un colchón de microesferas por el que circula aire caliente, que mantiene al paciente 'flotando', indicada en grandes quemados, es la:","Cama de levitación o fluidificada",["Cama electrocircular","Cama Roto-Rest","Cama de Foster"],"La electrocircular gira en sentido vertical; la Roto-Rest oscila lateralmente.");
D(2,"T","La cama que mantiene al paciente girando constantemente de lado a lado para repartir los puntos de presión se denomina:","Cama Roto-Rest",["Cama de levitación","Cama de Judet","Cama libro"],"La cama libro permite la angulación lateral, pero no el giro continuo automático.");
D(2,"T","Al hacer la cama, el hule o protector impermeable se coloca:","Debajo de la entremetida",["Encima de la entremetida","Debajo de la sábana bajera","Entre la encimera y la manta"],"Orden desde el colchón: cubrecolchón, bajera, hule, entremetida, encimera, manta y colcha.");
D(2,"T","El instrumento que se utiliza para auscultar, y que junto con el esfigmomanómetro permite medir la tensión arterial, es el:","Fonendoscopio",["Otoscopio","Oftalmoscopio","Laringoscopio"],"El esfigmomanómetro por sí solo mide la presión; el fonendoscopio permite oír los ruidos de Korotkoff.");
D(2,"T","El triángulo o estribo que cuelga del marco de Balkan sirve para:","Que el paciente pueda incorporarse y ayudar en su movilización",["Aplicar la tracción sobre la extremidad","Sujetar los sueros","Evitar que la ropa roce al paciente"],"La tracción se aplica mediante poleas y pesas; lo que evita el roce es el arco de cama.");
D(2,"P","Antes de trasladar a un paciente con oxigenoterapia, le piden que compruebe si la bala portátil tiene carga suficiente. Debe mirar:","El manómetro",["El caudalímetro","El humidificador","El color de la ojiva"],"El manómetro indica la presión restante en la bala.");

/* ================= TEMA 3 ================= */
D(3,"T","El plano anatómico que divide el cuerpo en mitad derecha y mitad izquierda es el:","Plano sagital",["Plano frontal o coronal","Plano transversal","Plano horizontal"],"El frontal o coronal divide en anterior y posterior; el transversal, en superior e inferior.");
D(3,"T","El movimiento por el que una extremidad se aleja de la línea media del cuerpo se denomina:","Abducción",["Aducción","Pronación","Circunducción"],"Aducción es el movimiento contrario: acercar a la línea media.");
D(3,"T","El movimiento del antebrazo que deja la palma de la mano hacia arriba se denomina:","Supinación",["Pronación","Abducción","Extensión"],"En la pronación la palma queda hacia abajo.");
D(3,"T","En la posición de Sims clásica, el paciente se encuentra:","En decúbito lateral izquierdo, con la pierna derecha flexionada por delante",["En decúbito lateral derecho, con la pierna izquierda flexionada por delante","En decúbito lateral izquierdo, con ambas piernas extendidas","En decúbito prono, con la pierna izquierda flexionada"],"Posición semiprona o de Sims: lateral izquierdo, brazo izquierdo hacia atrás y pierna derecha flexionada.");
D(3,"T","La posición de semi-Fowler supone una elevación de la cabecera de aproximadamente:","30 grados",["45 grados","60 grados","90 grados"],"Fowler: 45 grados. Fowler alta: 90 grados.");
D(3,"T","La posición en la que el paciente está sentado e inclinado hacia delante, apoyando los brazos sobre una mesa, para facilitar la respiración, es la:","Posición ortopneica",["Posición de Fowler alta","Posición genupectoral","Posición de Roser"],"En la Fowler alta el paciente está a 90 grados, pero apoyado hacia atrás.");
D(3,"T","Para una punción lumbar, el paciente se coloca habitualmente en:","Decúbito lateral con la espalda arqueada, en posición fetal",["Decúbito prono con los brazos extendidos","Decúbito supino con las piernas flexionadas","Posición de Roser"],"También puede hacerse sentado, con el tronco flexionado hacia delante.");
D(3,"T","En decúbito lateral, las úlceras por presión aparecen con más frecuencia en:","Trocánter y maléolos",["Sacro y talones","Isquion y omóplatos","Occipital y codos"],"Sacro, talones, occipital y codos corresponden al decúbito supino; el isquion, a la sedestación.");
D(3,"T","En sedestación, la zona de mayor riesgo de úlcera por presión es:","La tuberosidad isquiática",["El trocánter mayor","El maléolo externo","La cresta ilíaca"],"Cresta ilíaca: decúbito prono. Trocánter y maléolo: decúbito lateral.");
D(3,"T","Las disposiciones mínimas de seguridad y salud relativas a la manipulación manual de cargas se regulan en:","El Real Decreto 487/1997, de 14 de abril",["El Real Decreto 486/1997, de 14 de abril","El Real Decreto 488/1997, de 14 de abril","El Real Decreto 485/1997, de 14 de abril"],"485: señalización. 486: lugares de trabajo. 487: manipulación manual de cargas. 488: pantallas de visualización.");
D(3,"T","Según la Guía Técnica del INSST, en postura sentada no se deberían manipular cargas superiores a:","5 kg",["3 kg","10 kg","15 kg"],"15 kg es el límite recomendado para mujeres, jóvenes o mayores en condiciones ideales, de pie.");
D(3,"T","Según la Guía Técnica del INSST, el peso máximo recomendado para proteger a la mayoría de la población, incluidas mujeres, trabajadores jóvenes o mayores, es de:","15 kg",["25 kg","20 kg","40 kg"],"25 kg es el máximo general en condiciones ideales; 40 kg, para trabajadores sanos y entrenados de forma esporádica.");
D(3,"T","Al mover un objeto pesado sobre ruedas, desde el punto de vista de la mecánica corporal es preferible:","Empujar antes que tirar",["Tirar antes que empujar","Levantar antes que deslizar","Girar el tronco antes que mover los pies"],"Empujar aprovecha el peso del cuerpo; también es preferible deslizar a levantar.");
D(3,"T","Un paciente hemipléjico que utiliza bastón debe llevarlo:","En la mano del lado sano",["En la mano del lado afectado","Alternando de mano en cada paso","En la mano dominante, sea cual sea"],"El bastón amplía la base de apoyo desde el lado con fuerza.");
D(3,"T","Al subir escaleras, un paciente con una pierna afectada debe adelantar primero:","La pierna sana",["La pierna afectada","El bastón y la pierna afectada a la vez","Es indiferente"],"Regla: se sube con la sana y se baja con la afectada.");
D(3,"T","Durante el traslado de un paciente con drenaje torácico, el sistema colector debe mantenerse:","Vertical y por debajo del nivel del tórax",["Vertical y a la altura del tórax","Tumbado sobre la cama, junto al paciente","Por encima del tórax para evitar el reflujo"],"Si se eleva, el contenido puede refluir a la cavidad pleural.");
D(3,"T","El aislamiento cuya finalidad es proteger al paciente inmunodeprimido de los microorganismos del entorno se denomina:","Aislamiento protector o inverso",["Aislamiento estricto","Aislamiento de contacto","Aislamiento respiratorio"],"En los demás se protege al entorno frente al paciente.");
D(3,"T","Al colocarse el equipo de protección para entrar en una habitación de aislamiento, la última prenda que se pone son:","Los guantes",["La mascarilla","La bata","Las gafas"],"Los guantes van sobre los puños de la bata. Al retirar el equipo, son lo primero que se quita.");
D(3,"P","Le piden trasladar en camilla a una gestante de 36 semanas, consciente y sin otra indicación. La posición de elección es:","Decúbito lateral izquierdo",["Decúbito lateral derecho","Decúbito supino","Trendelenburg"],"Evita la compresión de la vena cava inferior por el útero.");
D(3,"P","Debe acompañar a un paciente con hemiplejia derecha que baja unas escaleras con bastón. Usted se sitúa:","Delante y hacia su lado derecho, y el paciente adelanta primero la pierna derecha",["Detrás y hacia su lado izquierdo, y el paciente adelanta primero la pierna izquierda","Delante y hacia su lado izquierdo, y el paciente adelanta primero la pierna izquierda","Detrás y hacia su lado derecho, y el paciente adelanta primero la pierna izquierda"],"Para bajar se adelanta la pierna afectada; el celador se coloca por delante y del lado afectado.");
D(3,"P","Tiene que pasar de la cama a la silla a un paciente con hemiplejia izquierda. La silla se coloca:","En el lado derecho del paciente, frenada y paralela o en ligero ángulo con la cama",["En el lado izquierdo del paciente, frenada y paralela a la cama","A los pies de la cama, sin frenar para poder acercarla","En el lado derecho del paciente, sin frenar para acompañar el giro"],"La silla va del lado sano y siempre frenada.");
D(3,"P","Traslada en cama a un paciente con traumatismo craneoencefálico, consciente. Salvo otra indicación, la cabecera irá:","Elevada unos 30 grados",["En Trendelenburg","Totalmente horizontal y sin almohada","Elevada 90 grados"],"La elevación moderada favorece el retorno venoso cerebral. Trendelenburg está contraindicado.");

/* ================= TEMA 4 ================= */
D(4,"T","La zona del bloque quirúrgico denominada 'semirrestringida' se corresponde con la:","Zona gris o limpia",["Zona blanca o estéril","Zona negra o de acceso","Zona de intercambio"],"Negra: sin restricción. Gris: semirrestringida. Blanca: restringida.");
D(4,"T","Dentro del equipo quirúrgico, forma parte del personal estéril:","La enfermera instrumentista",["La enfermera circulante","El anestesista","El celador"],"Estériles: cirujano, ayudantes e instrumentista. No estériles: anestesista, circulante y celador.");
D(4,"T","Según la clasificación de Spaulding, el material que entra en contacto con mucosas o con piel no intacta es:","Semicrítico",["Crítico","No crítico","Biológico"],"Crítico: tejidos estériles o sistema vascular. No crítico: piel intacta.");
D(4,"T","Según la clasificación de Spaulding, el material que entra en contacto con piel intacta es:","No crítico",["Semicrítico","Crítico","Subcrítico"],"La diferencia con el semicrítico es 'piel intacta' frente a 'piel no intacta o mucosas'.");
D(4,"T","El material clasificado como crítico según Spaulding requiere:","Esterilización",["Desinfección de alto nivel","Desinfección de nivel intermedio","Limpieza y secado"],"El semicrítico requiere, como mínimo, desinfección de alto nivel.");
D(4,"T","La cirugía mayor ambulatoria se caracteriza porque el paciente:","Es intervenido y vuelve a su domicilio el mismo día, sin ingreso",["Es intervenido con anestesia local en la consulta","Ingresa la víspera y recibe el alta al día siguiente","Es intervenido de urgencia y pasa a observación"],"Requiere quirófano y cuidados postoperatorios de corta duración, pero no hospitalización.");
D(4,"T","La cirugía que se realiza para aliviar los síntomas sin eliminar la causa de la enfermedad se denomina:","Paliativa",["Curativa","Reparadora","Exploradora"],"La curativa elimina la causa; la reparadora devuelve la función o el aspecto.");
D(4,"T","La duración recomendada por la OMS para la higiene de manos por fricción con solución hidroalcohólica es de:","20 a 30 segundos",["40 a 60 segundos","5 a 10 segundos","2 a 3 minutos"],"40 a 60 segundos corresponde al lavado con agua y jabón.");
D(4,"T","Para las intervenciones de hemorroides o de quiste pilonidal se coloca al paciente en posición de:","Kraske o navaja",["Litotomía","Sims","Trendelenburg"],"Decúbito prono con la mesa angulada a nivel de la cadera.");
D(4,"T","En las intervenciones de tiroides y de vesícula biliar, la mesa quirúrgica suele colocarse en:","Antitrendelenburg o Morestin",["Trendelenburg","Kraske","Litotomía"],"El Trendelenburg se usa en cirugía de abdomen inferior y pelvis.");
D(4,"T","En un internamiento no voluntario urgente, el tribunal debe ratificar la medida en el plazo máximo de:","72 horas desde que el internamiento llegue a su conocimiento",["24 horas desde que el internamiento llegue a su conocimiento","72 horas desde el ingreso del paciente","48 horas desde la comunicación del centro"],"Artículo 763 LEC: el centro comunica en 24 horas; el tribunal ratifica en 72 desde que tiene conocimiento.");
D(4,"T","Según el artículo 763 de la Ley de Enjuiciamiento Civil, los facultativos informarán periódicamente al tribunal sobre la necesidad de mantener el internamiento, salvo que se señale un plazo inferior:","Cada seis meses",["Cada tres meses","Cada doce meses","Cada mes"],"Informes periódicos semestrales, sin perjuicio de los que el tribunal requiera.");
D(4,"T","El orden en que deben intentarse las medidas de contención ante un paciente agitado es:","Verbal, farmacológica y mecánica",["Verbal, mecánica y farmacológica","Mecánica, verbal y farmacológica","Farmacológica, verbal y mecánica"],"La contención mecánica es siempre el último recurso.");
D(4,"T","En la contención mecánica parcial se sujetan:","El tronco y dos extremidades en diagonal",["El tronco y dos extremidades del mismo lado","Las cuatro extremidades, sin el tronco","Una extremidad superior y la cabeza"],"Por ejemplo, brazo derecho y pierna izquierda. La completa incluye tronco y cuatro extremidades.");
D(4,"T","Señale la INCORRECTA respecto a la contención mecánica:","Las sujeciones se fijan a las barandillas de la cama",["Se utiliza material homologado, nunca vendas ni sábanas","Debe revisarse periódicamente el estado del paciente y de los puntos de sujeción","Debe quedar registrada en la historia clínica"],"Las sujeciones se fijan al bastidor de la cama, nunca a las barandillas.");
D(4,"P","En el antequirófano, el celador se coloca gorro, calzas y mascarilla para pasar a la zona restringida. La mascarilla es obligatoria:","En la zona restringida, cubriendo nariz y boca en todo momento",["Desde la zona negra, aunque puede llevarse bajo la nariz","Solo dentro del quirófano y solo durante la incisión","Solo para el personal estéril"],"En la zona blanca o restringida la mascarilla es obligatoria para todo el personal.");
D(4,"P","En quirófano le piden que ayude a colocar a una paciente para una histerectomía vaginal. La posición será:","Litotomía, con las piernas en las perneras, colocándolas y retirándolas a la vez",["Litotomía, colocando primero una pierna y después la otra","Kraske, con la mesa angulada en la cadera","Trendelenburg, con las piernas extendidas"],"Las dos piernas se suben y bajan simultáneamente para evitar lesiones lumbares y de cadera.");
D(4,"P","Durante una intervención, el cirujano le pide que acerque el arco de radioscopia. Usted:","Lo aproxima con cuidado de no rozar el campo estéril, se protege con delantal plomado y no lo maneja",["Lo aproxima y realiza los disparos que le indiquen","Se niega, porque mover aparatos no es función del celador","Lo aproxima sin protección, porque la exposición es breve"],"Trasladar aparatos sí es función del celador; manejarlos corresponde al personal técnico.");
D(4,"P","Un paciente ingresado voluntariamente en psiquiatría, agitado, es contenido mecánicamente de forma urgente por enfermería antes de que llegue el psiquiatra. Esta actuación:","Es correcta si se comunica de inmediato al médico para que la confirme o la retire",["Es incorrecta: solo el médico puede iniciarla en cualquier caso","Es correcta y no precisa indicación médica posterior","Es correcta solo si la autoriza previamente el juez"],"La indicación es médica, pero en urgencia enfermería puede iniciarla y recabar la confirmación.");

/* ================= TEMA 5 ================= */
D(5,"T","La norma vigente que regula la sanidad mortuoria en Galicia es:","El Decreto 129/2023, de 31 de agosto",["El Decreto 151/2014, de 20 de noviembre","El Decreto 134/1998, de 23 de abril","El Decreto 2263/1974, de 20 de julio"],"El Decreto 129/2023 vino a sustituir al Decreto 151/2014. El 2263/1974 es el reglamento estatal.");
D(5,"T","Según el Decreto 129/2023, lo que queda del cuerpo humano una vez transcurridos cinco años y terminada la destrucción de los tejidos blandos, sin esqueletización completa, son:","Restos cadavéricos",["Restos óseos","Restos humanos","Cadáver"],"Restos óseos: con la esqueletización completada. Restos humanos: partes del cuerpo procedentes de abortos, mutilaciones, intervenciones, autopsias.");
D(5,"T","Según el Decreto 129/2023, las partes del cuerpo humano procedentes de abortos, mutilaciones, intervenciones quirúrgicas o autopsias se denominan:","Restos humanos",["Restos cadavéricos","Restos óseos","Residuos sanitarios"],"No confundir con restos cadavéricos, que proceden de un cadáver pasados cinco años.");
D(5,"T","Según el Decreto 129/2023, el método que retrasa la aparición de la putrefacción mediante sustancias químicas o reducción de la temperatura es:","La conservación transitoria",["El embalsamamiento","La tanatoestética","La refrigeración exclusivamente"],"El embalsamamiento 'impide' la putrefacción; la conservación transitoria la 'retrasa'.");
D(5,"T","Según el Decreto 129/2023, el método químico que impide la aparición de los fenómenos de putrefacción es:","El embalsamamiento",["La conservación transitoria","La congelación","La tanatoestética"],"Retrasar: conservación transitoria. Impedir: embalsamamiento.");
D(5,"T","En la clasificación sanitaria de los cadáveres del Decreto 129/2023, los que presentan riesgo radiológico por contener sustancias o productos radiactivos pertenecen al:","Grupo II",["Grupo I","Grupo III","Grupo IV"],"Grupo I: enfermedades infecciosas del anexo I. Grupo III: sin los riesgos anteriores.");
D(5,"T","Con carácter general, el Decreto 129/2023 establece que la inhumación de un cadáver se realizará, desde el fallecimiento:","Entre las 12 y las 48 horas",["Entre las 24 y las 48 horas","Entre las 24 y las 72 horas","Entre las 12 y las 72 horas"],"La normativa estatal de 1974 y el anterior decreto gallego fijaban 24 horas de mínimo; el vigente lo fija en 12.");
D(5,"T","Según el Decreto 129/2023, es obligatoria la conservación transitoria cuando la inhumación o incineración vaya a producirse:","Entre las 48 y las 96 horas tras el fallecimiento",["Entre las 24 y las 48 horas tras el fallecimiento","Después de las 96 horas tras el fallecimiento","Entre las 12 y las 48 horas tras el fallecimiento"],"Pasadas las 96 horas es obligatorio el embalsamamiento.");
D(5,"T","La prolongación artificial de la vida de un enfermo sin posibilidad de curación, también llamada encarnizamiento terapéutico, se denomina:","Distanasia",["Ortotanasia","Eutanasia","Tanatopraxia"],"La ortotanasia es la muerte natural, sin acortar ni prolongar artificialmente la agonía.");
D(5,"T","La muerte natural de un enfermo desahuciado, sin someterlo a una prolongación médicamente inútil de su agonía, se denomina:","Ortotanasia",["Distanasia","Eutanasia activa","Cacotanasia"],"Distanasia es justo lo contrario: prolongar artificialmente.");
D(5,"T","Según el Real Decreto 2230/1982, la sala de autopsias debe tener una superficie mínima de:","20 metros cuadrados",["15 metros cuadrados","25 metros cuadrados","30 metros cuadrados"],"Dotada de mesa de autopsias, agua corriente fría y caliente, sistema de aspiración y desagüe accesible, entre otros.");
D(5,"T","Según el Real Decreto 2230/1982, los refrigeradores de cadáveres deben tener capacidad para:","Dos cadáveres cada 200 camas de hospitalización o fracción",["Un cadáver cada 200 camas de hospitalización o fracción","Dos cadáveres cada 100 camas de hospitalización o fracción","Cuatro cadáveres cada 500 camas de hospitalización"],"Requisito de los locales para la práctica de autopsias clínicas.");
D(5,"T","Según la Ley 29/1980, podrá practicarse la autopsia clínica a los pacientes fallecidos en el hospital siempre que no hubiesen manifestado su oposición, por sí mismos o a través de:","Su cónyuge o familiares en primer grado",["Su cónyuge o familiares hasta el segundo grado","Cualquier familiar o allegado","Su representante legal exclusivamente"],"La ley se refiere al cónyuge o familiares en primer grado.");
D(5,"T","El instrumento utilizado en la autopsia para seccionar las costillas es el:","Costotomo",["Enterotomo","Craneotomo","Escoplo"],"El enterotomo abre el intestino; el craneotomo, el cráneo.");
D(5,"T","Para la apertura del raquis durante la autopsia, el cadáver se coloca en:","Decúbito prono",["Decúbito supino","Decúbito lateral izquierdo","Posición de Roser"],"El resto de la autopsia se realiza habitualmente en decúbito supino.");
D(5,"T","La técnica de autopsia en la que los órganos se extraen y examinan uno a uno es la de:","Virchow",["Ghon","Letulle","Rokitansky"],"Ghon: extracción por bloques. Letulle: en una sola masa. Rokitansky: disección in situ.");
D(5,"T","La técnica de autopsia en la que se extraen todas las vísceras en un solo bloque o masa es la de:","Letulle",["Ghon","Virchow","Rokitansky"],"En la de Ghon se extraen varios bloques de órganos relacionados, no uno solo.");
D(5,"T","La rigidez cadavérica comienza habitualmente por los músculos de:","La mandíbula y la cara, y progresa en sentido descendente",["Las extremidades inferiores, y progresa en sentido ascendente","El abdomen, y se extiende hacia las extremidades","Las manos y los pies simultáneamente"],"Ley de Nysten: progresión descendente; desaparece en el mismo orden.");
D(5,"P","Fallece un paciente con una enfermedad infecciosa incluida en el anexo I del Decreto 129/2023. A efectos de sanidad mortuoria, ese cadáver se clasifica en el:","Grupo I",["Grupo II","Grupo III","Grupo de riesgo biológico IV"],"El grupo I comprende los cadáveres con riesgo para la salud pública o profesional por enfermedad infecciosa.");
D(5,"P","Un familiar le pregunta si pueden enterrar a su padre, fallecido esta mañana a las 8:00 en Galicia y sin autopsia ni donación, esta misma tarde a las 17:00. Al margen de remitirle a quien deba informarle, conforme al Decreto 129/2023:","No sería posible con carácter general: deben transcurrir al menos 12 horas",["Sí sería posible: basta con disponer de la licencia de enterramiento","No sería posible: deben transcurrir al menos 24 horas","Sí sería posible si lo autoriza el médico que certificó la muerte"],"Mínimo de 12 horas, con excepciones como los autopsiados o los donantes de órganos.");
D(5,"P","En la sala de autopsias, el patólogo delega verbalmente en el celador la apertura del cráneo con la sierra. El celador:","No puede hacerlo: no le corresponde usar instrumental alguno sobre el cadáver",["Puede hacerlo si la delegación consta por escrito","Puede hacerlo si es con sierra eléctrica y no con bisturí","Puede hacerlo solo en las autopsias clínicas, no en las judiciales"],"La limitación de la función 20ª no admite delegación.");

/* ================= TEMA 6 ================= */
D(6,"T","El sistema de almacenaje en el que cada artículo se coloca en cualquier hueco libre, sin ubicación fija, se denomina:","Caótico o de hueco libre",["Ordenado o de hueco fijo","Rotativo","Por bloques apilados"],"En el ordenado cada referencia tiene asignada una ubicación fija.");
D(6,"T","El inventario que se mantiene actualizado de forma continua, registrando cada entrada y salida, es el:","Inventario permanente",["Inventario periódico","Inventario rotativo","Inventario inicial"],"El periódico se hace en fechas fijas; el rotativo recuenta por secciones a lo largo del año.");
D(6,"T","El inventario que consiste en recontar cada cierto tiempo una parte distinta de los artículos, de forma que al final del periodo se han contado todos, es el:","Inventario rotativo o cíclico",["Inventario permanente","Inventario periódico","Inventario final"],"No exige cerrar el almacén para el recuento.");
D(6,"T","En la clasificación ABC, los artículos del grupo C son:","Muchos artículos que representan una pequeña parte del valor",["Pocos artículos que representan la mayor parte del valor","Artículos de valor y cantidad intermedios","Artículos sin rotación que deben retirarse"],"A: pocos y de mucho valor. B: intermedios. C: muchos y de poco valor.");
D(6,"T","La comprobación de que el número de bultos y unidades recibidas coincide con el albarán y el pedido es una recepción:","Cuantitativa",["Cualitativa","Administrativa","Provisional"],"La cualitativa comprueba el estado, la calidad y las características del producto.");
D(6,"T","El documento por el que el centro solicita al proveedor el envío de determinados artículos es:","La hoja de pedido",["El albarán","La factura","El vale de almacén"],"El albarán acompaña a la mercancía; el vale justifica una salida interna del almacén.");
D(6,"T","El traslado de material desde el almacén general hasta las unidades de hospitalización es un suministro:","Interno",["Externo","Directo de proveedor","En tránsito"],"El externo va del proveedor al almacén.");
D(6,"T","El criterio LIFO de gestión de existencias significa que:","Lo último que entra es lo primero que sale",["Lo primero que entra es lo primero que sale","Lo primero que caduca es lo primero que sale","Lo último que entra es lo último que sale"],"FIFO: primero en entrar, primero en salir. FEFO: primero en caducar, primero en salir.");
D(6,"P","En el almacén reciben un pedido cuyo albarán indica 20 cajas; llegan 20 cajas, pero cinco contienen un artículo distinto del pedido. La incidencia se detecta en la recepción:","Cualitativa",["Cuantitativa","Contable","Diferida"],"El número de bultos es correcto; lo que falla es la naturaleza del producto.");
D(6,"P","Un celador de almacén, sentado ante una mesa de preparación de pedidos, debe pasar repetidamente cajas a un carro. Según la Guía Técnica del INSST, en esa postura no debería manipular cargas de más de:","5 kg",["15 kg","10 kg","25 kg"],"En postura sentada el límite recomendado es de 5 kg.");

/* ================= TEMA 7 ================= */
D(7,"T","El medicamento destinado a un paciente individualizado, preparado por el farmacéutico o bajo su dirección para cumplimentar una prescripción facultativa detallada, es:","Una fórmula magistral",["Un preparado oficinal","Una especialidad farmacéutica","Un medicamento genérico"],"El preparado oficinal se elabora según el Formulario Nacional y se dispensa directamente a los pacientes de esa farmacia.");
D(7,"T","El indicador biológico utilizado para controlar la esterilización por vapor de agua contiene esporas de:","Geobacillus stearothermophilus",["Bacillus atrophaeus","Clostridium tetani","Staphylococcus aureus"],"Bacillus atrophaeus (antes subtilis) se emplea para óxido de etileno y calor seco.");
D(7,"T","El indicador biológico utilizado para controlar la esterilización por óxido de etileno contiene esporas de:","Bacillus atrophaeus",["Geobacillus stearothermophilus","Escherichia coli","Bacillus anthracis"],"Geobacillus stearothermophilus se usa para vapor y para peróxido de hidrógeno.");
D(7,"T","Las temperaturas habituales de los ciclos de esterilización en autoclave de vapor son:","121 y 134 grados centígrados",["100 y 110 grados centígrados","160 y 180 grados centígrados","37 y 55 grados centígrados"],"160-180: calor seco. 37-55: óxido de etileno.");
D(7,"T","El método de esterilización a baja temperatura que no deja residuos tóxicos y no es compatible con celulosa ni tejidos es:","El gas plasma de peróxido de hidrógeno",["El óxido de etileno","El formaldehído","El vapor de agua"],"El óxido de etileno es tóxico y exige aireación.");
D(7,"T","La sustancia química que destruye o inhibe microorganismos y se aplica sobre piel o mucosas es:","Un antiséptico",["Un desinfectante","Un esterilizante","Un detergente"],"El desinfectante se aplica sobre objetos y superficies inanimados.");
D(7,"T","Los indicadores que cambian de color al exponerse a las condiciones del proceso de esterilización son los controles:","Químicos",["Físicos","Biológicos","Microbiológicos"],"Físicos: termómetros, manómetros y registros gráficos del equipo.");
D(7,"T","En el aseo completo del paciente encamado, la última zona que se lava es:","La región genital y perianal",["La espalda y las nalgas","Las extremidades inferiores","El abdomen"],"Orden: cara, cuello, brazos, tórax, abdomen, piernas, espalda y nalgas, y por último genitales y región anal.");
D(7,"T","La temperatura adecuada del agua para el aseo del paciente encamado es, aproximadamente, de:","37 a 40 grados centígrados",["30 a 33 grados centígrados","42 a 45 grados centígrados","25 a 28 grados centígrados"],"Salvo indicación contraria.");
D(7,"T","Las dimensiones del formato DIN A3 son:","297 x 420 mm",["210 x 297 mm","420 x 594 mm","148 x 210 mm"],"A4: 210 x 297. A2: 420 x 594. A5: 148 x 210.");
D(7,"T","Para reducir un original DIN A3 a una copia DIN A4, la escala que debe seleccionarse en la fotocopiadora es aproximadamente del:","71 %",["50 %","141 %","86 %"],"141 % es la ampliación de A4 a A3. El 50 % reduciría la superficie a la cuarta parte.");
D(7,"T","El formato DIN A0, del que derivan los demás de la serie A, tiene una superficie de:","Un metro cuadrado",["Medio metro cuadrado","Dos metros cuadrados","Un metro por un metro de lado"],"Mide 841 x 1189 mm; su superficie es 1 m², pero no es cuadrado.");
D(7,"T","El 'gramaje' de un papel expresa:","Su peso en gramos por metro cuadrado",["Su peso en gramos por hoja","Su grosor en micras","Su peso en gramos por paquete de 500 hojas"],"El papel de oficina habitual es de 80 g/m².");
D(7,"T","La historia clínica electrónica del Servizo Galego de Saúde se denomina:","IANUS",["DIRAYA","SELENE","SIGLO"],"Diraya es la del Servicio Andaluz de Salud.");
D(7,"P","Debe llevar a la central de esterilización un contenedor de instrumental usado y, de vuelta, material estéril para la planta. Lo correcto es:","Usar circuitos y carros diferenciados para el material sucio y el estéril",["Usar el mismo carro, colocando lo estéril en la balda superior","Usar el mismo carro, cubriendo lo estéril con un paño limpio","Usar el mismo carro si se desinfecta con alcohol entre ambos trayectos"],"El circuito sucio y el limpio no deben cruzarse ni compartir medio de transporte.");
D(7,"P","Le piden fotocopiar un informe ampliándolo de DIN A4 a DIN A3. Seleccionará una escala aproximada del:","141 %",["200 %","71 %","122 %"],"El A3 tiene el doble de superficie, pero cada lado solo aumenta un 41 %.");
D(7,"P","Colabora con la TCAE en el aseo de una paciente encamada. Para la higiene genital, la limpieza se realiza:","De delante hacia atrás, del pubis hacia el ano",["De atrás hacia delante, del ano hacia el pubis","Con movimientos circulares de fuera hacia dentro","En cualquier sentido, si se usa esponja jabonosa"],"Evita arrastrar microorganismos de la zona anal hacia la uretra.");

/* ================= TEMA 8 ================= */
D(8,"T","En el Sistema de Triaje Manchester, al color amarillo le corresponde un tiempo máximo de atención de:","60 minutos",["10 minutos","120 minutos","240 minutos"],"Rojo: inmediato. Naranja: 10. Amarillo: 60. Verde: 120. Azul: 240.");
D(8,"T","En el Sistema de Triaje Manchester, al color verde le corresponde un tiempo máximo de atención de:","120 minutos",["60 minutos","240 minutos","30 minutos"],"El verde es 'normal' o menos urgente; el azul, no urgente, 240 minutos.");
D(8,"T","En el triaje de catástrofes con múltiples víctimas (método START), el color negro identifica a:","Los fallecidos o sin posibilidad de supervivencia",["Los heridos muy graves de atención inmediata","Los heridos leves que pueden caminar","Los pacientes no urgentes"],"No confundir con el Manchester, que no usa el negro y sí el azul para lo no urgente.");
D(8,"T","El transporte sanitario que traslada al paciente desde el lugar donde se produce la urgencia hasta el centro sanitario se denomina:","Transporte primario",["Transporte secundario","Transporte terciario","Transporte programado"],"Secundario: entre centros sanitarios. Terciario: dentro del propio centro.");
D(8,"T","El traslado de un paciente de un hospital a otro es un transporte:","Secundario o interhospitalario",["Primario o extrahospitalario","Terciario o intrahospitalario","Asistido de primer nivel"],"El terciario se realiza dentro del mismo hospital.");
D(8,"T","Según el Real Decreto 836/2012, las ambulancias asistenciales de clase B deben contar al menos con:","Un conductor con el título de técnico en emergencias sanitarias y otro técnico en emergencias sanitarias en funciones de ayudante",["Un conductor con permiso de conducción y un enfermero","Un conductor técnico en emergencias sanitarias, un enfermero y un médico","Un conductor con certificado de profesionalidad, sin ayudante"],"Clase C: conductor TES y enfermero, más médico cuando la asistencia lo requiera.");
D(8,"T","En la cadena de supervivencia, el eslabón que sigue inmediatamente a la RCP precoz es:","La desfibrilación precoz",["El reconocimiento precoz y la petición de ayuda","Los cuidados posresucitación","El soporte vital avanzado en el hospital"],"Orden: reconocimiento y alerta, RCP precoz, desfibrilación precoz y cuidados posresucitación.");
D(8,"T","La profundidad recomendada de las compresiones torácicas en la RCP del adulto es de:","5 a 6 centímetros",["3 a 4 centímetros","7 a 8 centímetros","Un tercio del diámetro del tórax, como mínimo 8 centímetros"],"Con una frecuencia de 100 a 120 por minuto.");
D(8,"T","La maniobra de apertura de la vía aérea indicada cuando se sospecha lesión cervical es:","La tracción o elevación mandibular",["La maniobra frente-mentón","La hiperextensión del cuello","La maniobra de Heimlich"],"La maniobra frente-mentón implica extender el cuello y se evita ante sospecha de lesión cervical.");
D(8,"T","Ante un adulto consciente con obstrucción grave de la vía aérea por cuerpo extraño, la secuencia recomendada es:","Cinco golpes interescapulares alternados con cinco compresiones abdominales",["Cinco compresiones abdominales seguidas de dos ventilaciones","Treinta compresiones torácicas y dos ventilaciones","Animarle a toser y darle agua"],"Si pierde la consciencia se inicia la RCP. Animar a toser se reserva para la obstrucción leve.");
D(8,"T","En Galicia, las siglas PAC designan:","El punto de atención continuada",["El plan de atención al ciudadano","El programa de atención a crónicos","El puesto de asistencia clínica"],"Presta la atención urgente en atención primaria fuera del horario ordinario.");
D(8,"T","Se entiende por emergencia, a diferencia de la urgencia, aquella situación en la que:","Existe peligro inmediato para la vida o la función de un órgano",["La atención puede demorarse unas horas sin riesgo","El paciente percibe la necesidad de atención inmediata","La patología requiere ingreso programado"],"La percepción del paciente define la urgencia subjetiva, no la emergencia.");
D(8,"P","En la puerta de urgencias recibe a un paciente con una petición de eco-doppler. Debe acompañarlo o llevar la petición al servicio de:","Radiodiagnóstico",["Medicina nuclear","Laboratorio","Rehabilitación"],"La ecografía doppler es una técnica de diagnóstico por imagen.");
D(8,"P","Llega a urgencias un paciente con dolor torácico intenso acompañado de su familia, que le pregunta a usted si es un infarto. Lo correcto es:","Llevarlo de inmediato a triaje y remitir a la familia al médico que lo atienda para cualquier información",["Llevarlo a admisión para filiarlo y tranquilizar a la familia diciendo que no parece grave","Dejarlo en la sala de espera e informar a la familia de que será atendido por orden de llegada","Llevarlo directamente a un box y explicar a la familia las pruebas que le harán"],"Prioridad asistencial y abstención de comentarios clínicos.");
D(8,"P","El rótulo luminoso de la entrada de urgencias está averiado. El celador de puerta debe:","Dar cuenta a su superior inmediato",["Avisar directamente a la empresa instaladora","Anotarlo en el libro de triaje","Esperar a que lo comunique el personal de seguridad"],"Función 9ª del artículo 14.2.");
D(8,"P","En un accidente con varias víctimas llega a urgencias un herido etiquetado con tarjeta amarilla de triaje de catástrofes. Esa tarjeta indica que es un paciente:","Grave, cuya atención puede demorarse un tiempo sin riesgo vital inmediato",["De atención inmediata por riesgo vital","Leve, que puede caminar","Fallecido"],"Rojo: inmediato. Amarillo: diferible. Verde: leve. Negro: fallecido.");

/* ================= TEMA 9 ================= */
D(9,"T","En una hoja de cálculo, la referencia A1:B3 designa:","Un rango de seis celdas",["Dos celdas, A1 y B3","Un rango de tres celdas","Un rango de cuatro celdas"],"Los dos puntos indican rango: A1, A2, A3, B1, B2 y B3. 'A1;B3' serían solo dos celdas.");
D(9,"T","En una hoja de cálculo, la referencia $A$1 es:","Absoluta",["Relativa","Mixta","Circular"],"Relativa: A1. Mixta: $A1 o A$1.");
D(9,"T","La extensión propia de los documentos de texto de LibreOffice Writer es:",".odt",[".ods",".odp",".dot"],".ods es la hoja de cálculo Calc; .odp, la presentación Impress.");
D(9,"T","Un kilobyte equivale a:","1024 bytes",["1000 bits","1024 bits","8 bytes"],"Un byte son 8 bits; un kilobyte, 1024 bytes.");
D(9,"T","El protocolo que utiliza un programa de correo para ENVIAR los mensajes es:","SMTP",["POP3","IMAP","HTTP"],"POP3 e IMAP se usan para recibir.");
D(9,"T","El protocolo de recepción de correo que mantiene los mensajes en el servidor y los sincroniza entre varios dispositivos es:","IMAP",["POP3","SMTP","FTP"],"POP3, por defecto, descarga los mensajes al equipo y los elimina del servidor.");
D(9,"T","En la versión en español de Microsoft Word, la combinación Ctrl + G sirve para:","Guardar el documento",["Poner el texto en negrita","Ir a una página","Agrupar objetos"],"En Word en español, la negrita es Ctrl + N, la cursiva Ctrl + K y el subrayado Ctrl + S.");
D(9,"T","La red que permite a determinados usuarios externos autorizados, como proveedores, acceder a parte de la red interna de una organización se denomina:","Extranet",["Intranet","Internet","Red local"],"La intranet es de uso exclusivamente interno.");
D(9,"P","En una hoja de cálculo debe sumar únicamente las celdas A1 y A10. La fórmula correcta es:","=SUMA(A1;A10)",["=SUMA(A1:A10)","SUMA(A1;A10)","=SUMA(A1-A10)"],"Con dos puntos sumaría todo el rango de A1 a A10; sin el signo igual no es una fórmula.");

/* ================= TEMA 10 ================= */
D(10,"T","Según la Ley Orgánica 3/2007, la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular respecto de las del otro es:","Discriminación indirecta",["Discriminación directa","Acción positiva","Acoso por razón de sexo"],"La directa es el trato menos favorable por razón de sexo en situación comparable.");
D(10,"T","Según la Ley Orgánica 3/2007, cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo, es:","Acoso por razón de sexo",["Acoso sexual","Discriminación indirecta","Violencia económica"],"El acoso sexual es el comportamiento 'de naturaleza sexual'; el acoso por razón de sexo se realiza 'en función del sexo'.");
D(10,"T","Según la Ley Orgánica 3/2007, cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona es:","Acoso sexual",["Acoso por razón de sexo","Discriminación directa","Acoso laboral"],"La clave es 'de naturaleza sexual'.");
D(10,"T","Según la disposición adicional primera de la Ley Orgánica 3/2007, existe composición equilibrada cuando las personas de cada sexo:","No superan el 60 % ni son menos del 40 %",["Representan exactamente el 50 %","No superan el 70 % ni son menos del 30 %","No superan el 55 % ni son menos del 45 %"],"Regla del 60/40.");
D(10,"T","Según su artículo 2, la Ley gallega 11/2007 se aplica a las mujeres en situación de violencia de género que:","Vivan, residan o trabajen en Galicia",["Residan legalmente en Galicia","Estén empadronadas en Galicia","Tengan la vecindad civil gallega"],"Igualmente a sus hijas e hijos y a otras personas dependientes de ellas.");
D(10,"T","La visión del mundo que sitúa al hombre como centro y medida de todas las cosas se denomina:","Androcentrismo",["Misoginia","Machismo","Patriarcado"],"Misoginia: odio o aversión a las mujeres. Patriarcado: sistema de organización social basado en el dominio masculino.");
D(10,"T","En el ciclo de la violencia descrito por Leonore Walker, la fase que sigue a la de explosión o agresión es la de:","Luna de miel, arrepentimiento o reconciliación",["Acumulación de tensión","Negación y aislamiento","Denuncia y ruptura"],"Tras la luna de miel vuelve a iniciarse la acumulación de tensión.");
D(10,"T","El texto refundido de las disposiciones legales de la Comunidad Autónoma de Galicia en materia de igualdad fue aprobado por:","El Decreto legislativo 2/2015, de 12 de febrero",["La Ley 11/2007, de 27 de julio","La Ley Orgánica 3/2007, de 22 de marzo","El Decreto 129/2023, de 31 de agosto"],"La Ley 11/2007 es la de violencia de género.");
D(10,"T","La igualdad que consiste en el reconocimiento jurídico de los mismos derechos a mujeres y hombres se denomina:","Igualdad formal",["Igualdad real o efectiva","Equidad de género","Paridad"],"La igualdad real o efectiva exige además remover los obstáculos que impiden ejercer esos derechos.");
D(10,"P","En un servicio se exige para un puesto una estatura mínima que no guarda relación con las funciones y que excluye a la mayoría de las mujeres. Conforme a la Ley Orgánica 3/2007, se trata de:","Discriminación indirecta por razón de sexo",["Discriminación directa por razón de sexo","Una acción positiva","Acoso por razón de sexo"],"El criterio es aparentemente neutro, pero sitúa a un sexo en desventaja sin justificación objetiva.");
D(10,"P","Un compañero dirige de forma reiterada a una celadora comentarios despectivos sobre la capacidad de las mujeres para el trabajo, sin contenido sexual. Conforme a la Ley Orgánica 3/2007, esa conducta constituye:","Acoso por razón de sexo",["Acoso sexual","Discriminación indirecta","Violencia vicaria"],"No es de naturaleza sexual, sino realizada en función del sexo de la persona.");
